const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/packet-view.cjs');
test('view shares memory in both directions', () => {
  const source = Buffer.from([0x70,0x11,0x22]);
  const view = app.packetView(source,1,3);
  assert.ok(Buffer.isBuffer(view));
  assert.notEqual(view,source);
  view[0]=0x41;
  assert.equal(source.toString('hex'),'704122');
  source[2]=0x7f;
  assert.equal(view.toString('hex'),'417f');
});
test('relative indexes and default bounds', () => {
  const source = Buffer.from('abcdef');
  for (const [start,end,expected] of [
    [-3,-1,'de'], [1,99,'bcdef'], [4,2,''],
    [-99,2,'ab'], [undefined,undefined,'abcdef'], [2,undefined,'cdef']
  ]) assert.equal(app.packetView(source,start,end).toString(),expected);
});

