const test = require('node:test');
const assert = require('node:assert/strict');
const { packetView } = require('../lib/packet-view.cjs');
test('copy opt-in preserves bounds but isolates writes in both directions', () => {
  const source = Buffer.from('abcdef');
  const copy = packetView(source, -3, -1, true);
  assert.ok(Buffer.isBuffer(copy));
  assert.equal(copy.toString(), 'de');
  copy[0] = 88;
  assert.equal(source.toString(), 'abcdef');
  source[4] = 89;
  assert.equal(copy.toString(), 'Xe');
  const view = packetView(source, 1, 3, false);
  view[0] = 90;
  assert.equal(source[1], 90);
  assert.equal(packetView(source, 9, 2, true).length, 0);
  assert.equal(packetView(source, undefined, undefined, true).toString(), source.toString());
});

